export const commerceProduct=id=>[...commerceProducts,...travelProducts,...financialProducts,...socialProducts,...aiProducts,...researchProducts,...realEstateProducts].find(p=>p.id===id);
export const popularProducts=popularIds.map(commerceProduct);
export function productLinkAllowed(value,product){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&product.hosts.includes(u.hostname.replace(/^www\./,''));}catch{return false;}}
